begin;
set local statement_timeout='20s';
do $tests$
declare c uuid:=gen_random_uuid();u uuid:=gen_random_uuid();org uuid:=gen_random_uuid();generation uuid:=gen_random_uuid();season uuid:=gen_random_uuid();sg uuid:=gen_random_uuid();g uuid:=gen_random_uuid();team uuid:=gen_random_uuid();source uuid:=gen_random_uuid();cat jsonb;ctx jsonb;req jsonb;r jsonb;src jsonb;preview jsonb;old_preview jsonb;fid uuid;edited uuid;edited_source jsonb;manual uuid:=gen_random_uuid();mid uuid:=gen_random_uuid();rejected boolean;manual_before jsonb;
begin
 insert into auth.users(id,email) values(u,'group-management-'||u||'@example.invalid');
 insert into public.user_profiles(user_id,display_name) values(u,'Synthetic admin');
 insert into public.clubs(id,name,slug,created_by) values(c,'Any club','group-management-'||c,u);
 insert into public.club_memberships(club_id,user_id,role,permission_role,involvement) values(c,u,'admin','admin','player');
 insert into club_selection_private.access(club_id,mode,status,head_selector_id) values(c,'standalone','active',u);
 insert into public.playing_groups(id,club_id,name) values(g,c,'Existing grade');
 insert into club_selection_private.selection_groups(id,club_id,name) values(sg,c,'Original group');
 insert into club_selection_private.selection_group_grades values(c,g,sg);
 insert into club_selection_private.playhq_connections(club_id,organisation_id,association_id,secret_id,generation,updated_by,verified_at) values(c,org,gen_random_uuid(),gen_random_uuid(),generation,u,now());
 perform set_config('request.jwt.claim.sub',u::text,true);perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 cat:=public.playhq_store_teams(c,generation,season,jsonb_build_array(jsonb_build_object('id',team,'name','Club Sabres','club',jsonb_build_object('id',org),'grade',jsonb_build_object('id',source,'name','Summer competition'))));
 perform set_config('request.jwt.claims','{"role":"authenticated"}',true);
 ctx:=public.club_selection_groups(c,'context');req:=jsonb_build_object('request_id',gen_random_uuid(),'revision',ctx->'revision','name','Summer teams');
 ctx:=public.club_selection_group_manage(c,'add_group',req);assert ctx=public.club_selection_group_manage(c,'add_group',req),'Group retry is idempotent';
 assert (select count(*)=2 from club_selection_private.selection_groups where club_id=c),'One group added';
 assert (select selection_group_id=sg from club_selection_private.selection_group_grades where grade_id=g),'Original allocation untouched';
 select id into sg from club_selection_private.selection_groups where club_id=c and name='Summer teams';
 req:=jsonb_build_object('request_id',gen_random_uuid(),'revision',ctx->'revision','season_id',season,'catalogue_id',cat->>'catalogue_id','team_id',team,'selection_group_id',sg,'name','City Summer Bash');
 ctx:=public.club_selection_group_manage(c,'add_team',req);g:=(ctx->>'changed_grade_id')::uuid;
 assert ctx=public.club_selection_group_manage(c,'add_team',req),'Team retry is idempotent';
 assert (select count(*)=2 from public.playing_groups where club_id=c),'Only chosen team created';
 assert (select grade_id=g from club_selection_private.playhq_grade_mappings where club_id=c),'Preferred grade retains source ID';
 manual_before:=jsonb_build_object('grade','City Summer Bash','grade_group_id',g,'opposition','Visitors','format','t20','days',jsonb_build_array(jsonb_build_object('date','2099-11-15','ground','Manual ground')));
 insert into club_selection_private.fixtures(id,club_id,details) values(manual,c,manual_before);
 src:=jsonb_build_object('source_match_id',mid,'source_team_id',team,'source_grade_id',source,'format','t20','opposition','Visitors','days',jsonb_build_array(jsonb_build_object('date','2099-11-01','ground','Imported ground')));
 perform club_selection_private.playhq_import_all(c,season,source,team,jsonb_build_array(src,jsonb_set(jsonb_set(src,'{source_match_id}',to_jsonb(gen_random_uuid())),'{days,0,date}','"2099-11-08"'),jsonb_set(jsonb_set(src,'{source_match_id}',to_jsonb(gen_random_uuid())),'{days,0,date}','"2099-11-15"')));
 assert (select count(*)=2 from club_selection_private.playhq_links where club_id=c and import_created),'Provenance separates newly imported from pre-existing fixtures';
 select f.id into fid from club_selection_private.fixtures f where club_id=c and details#>>'{days,0,date}'='2099-11-08';
 update club_selection_private.fixtures set slots='[{"d1":"saved-player"}]',revision=revision+1 where id=fid;
 edited_source:=jsonb_set(jsonb_set(src,'{source_match_id}',to_jsonb(gen_random_uuid())),'{days,0,date}','"2099-12-01"');
 perform club_selection_private.playhq_import_all(c,season,source,team,jsonb_build_array(edited_source));
 select id into edited from club_selection_private.fixtures where club_id=c and details#>>'{days,0,date}'='2099-12-01';
 update club_selection_private.fixtures set details=jsonb_set(details,'{meeting}','"Meet at the clubhouse"'),revision=revision+1 where id=edited;
 edited_source:=jsonb_set(edited_source,'{days,0,ground}','"Updated source ground"');
 perform club_selection_private.playhq_import_all(c,season,source,team,jsonb_build_array(edited_source));
 assert (select l.import_touched and l.last_applied_revision=f.revision and f.details->>'meeting'='Meet at the clubhouse' and f.details#>>'{days,0,ground}'='Updated source ground' from club_selection_private.playhq_links l join club_selection_private.fixtures f on f.id=l.fixture_id where f.id=edited),'Automatic updates retain the persistent manual-change marker';
 assert not club_selection_private.playhq_import_removable(edited),'A later source update cannot make a manually edited fixture removable';
 preview:=public.club_selection_group_manage(c,'disconnect_preview',jsonb_build_object('season_id',season,'grade_id',g));
 assert preview->>'remove_count'='1' and preview->>'keep_count'='3','Preview keeps selected, edited and pre-existing fixtures';old_preview:=preview;
 perform club_selection_private.playhq_import_all(c,season,source,team,jsonb_build_array(jsonb_set(jsonb_set(src,'{source_match_id}',to_jsonb(gen_random_uuid())),'{days,0,date}','"2099-11-22"')));
 req:=jsonb_build_object('request_id',gen_random_uuid(),'revision',ctx->'revision','season_id',season,'grade_id',g,'token',old_preview->>'token');
 rejected:=false;begin perform public.club_selection_group_manage(c,'disconnect',req);exception when raise_exception then rejected:=true;end;assert rejected,'Changed fixtures require a fresh undo preview';
 preview:=public.club_selection_group_manage(c,'disconnect_preview',jsonb_build_object('season_id',season,'grade_id',g));req:=jsonb_set(req,'{token}',preview->'token');
 r:=public.club_selection_group_manage(c,'disconnect',req);assert r=public.club_selection_group_manage(c,'disconnect',req),'Disconnect retry is idempotent';
 assert r->>'removed'='2' and r->>'retained'='3' and r->>'restored'='1','Undo removes only untouched future imports and restores unchanged manual arrangements';
 assert (select details->>'meeting'='Meet at the clubhouse' from club_selection_private.fixtures where id=edited),'Manual arrangements survive disconnect after a later automatic update';
 assert (select slots#>>'{0,d1}'='saved-player' from club_selection_private.fixtures where id=fid),'Selection history retained';
 assert (select details=manual_before from club_selection_private.fixtures where id=manual),'Manual fixture restored';
 assert not exists(select 1 from club_selection_private.playhq_grade_mappings where club_id=c),'Wrong source mapping detached';
 assert not exists(select 1 from club_selection_private.playhq_links where club_id=c),'Wrong source polling stopped';
 assert (select active and name='City Summer Bash' from public.playing_groups where id=g),'Club grade retained for linking the correct team';
 assert not has_function_privilege('anon','public.club_selection_group_manage(uuid,text,jsonb)','EXECUTE'),'Anonymous management denied';
 assert not has_function_privilege('authenticated','club_selection_private.playhq_import_removable(uuid)','EXECUTE'),'Private fixture inspection denied';
end $tests$;
rollback;
select 'Incremental groups, trusted additions, preserved setup, reviewed undo, race protection and history preservation passed.' result;
